// FUNCTION: BFME2 0x003588E7 size=76 name=?getUnitNamed@ScriptEngine@@QAEPAVObject@@PAVParameter@@@Z evidence=N:ledger tier=B hypothesis:Z
Object *ScriptEngine::getUnitNamed(Parameter *pUnitParm)
{
	ObjectID id = (ObjectID)pUnitParm->m_objectStatus.m_bits[1];
	if (id)
	{
		Object *object = TheGameLogic->findObjectByID(id);
		if (object)
			return object;
	}
	if (pUnitParm->m_string.isEmpty())
		return 0;
	return getUnitNamed(pUnitParm->m_string);
}

